  "items": [
    {
      "title": "Duisburg Social Report 2010 – Employment Statistics, 2000–2008",
      "url_or_doi": "https://www.duisburg.de/vv/produkte/pro_du/dez_iii/50/102010100000077024.php.media/76457/Sozialbericht_Stadt_Duisburg_2010.pdf",
      "justification": "Highly relevant historical dataset published by the City of Duisburg. Table 21 on page 133 provides annual figures for employees subject to social insurance contributions residing in Duisburg from 2000 through 2008. It includes employment counts, working-age population figures, and employment rates. Particularly useful for analyzing employment trends throughout the 2000s. Data are available in PDF tables."
    },
    {
      "title": "Duisburg Social Report 2007 – Employment by District, 2000–2005",
      "url_or_doi": "https://www.duisburg.de/vv/produkte/pro_du/dez_iii/50/102010100000077024.php.media/85334/07_0248_Sozialbericht_2007_Stadt_Duisburg.pdf",
      "justification": "Official municipal report containing detailed employment statistics for Duisburg between 2000 and 2005. Includes employees subject to social insurance contributions, employment rates, and geographical breakdowns across Duisburg's administrative districts and neighborhoods. Particularly useful for examining spatial differences in employment and changes within the city during the early 2000s."
    },
    {
      "title": "Federal Employment Agency – Historical Unemployment and Employment Time Series",
      "url_or_doi": "https://statistik.arbeitsagentur.de/DE/Navigation/Statistiken/Fachstatistiken/Arbeitsuche-Arbeitslosigkeit-Unterbeschaeftigung/Produkte/Zeitreihen-Arbeitslose-Arbeitsuchende-Arbeitslosenquoten/Zeitreihen-Arbeitslose-Arbeitsuchende-Arbeitslosenquoten-Nav.html",
      "justification": "Official German Federal Employment Agency statistical resource providing historical labor-market time series for German districts and cities, including Duisburg. Contains unemployment counts, unemployment rates, registered vacancies, and other employment-related indicators. Historical coverage extends into the 2000s, making it particularly useful for reconstructing Duisburg's labor-market conditions between 2000 and 2009."
    },
    {
      "title": "Federal Employment Agency – Employment Statistics and Historical Employment Rates",
      "url_or_doi": "https://statistik.arbeitsagentur.de/DE/Navigation/Statistiken/Fachstatistiken/Beschaeftigung/Beschaeftigte/Beschaeftigte-Nav.html",
      "justification": "Official employment statistics portal containing datasets on employees subject to social insurance contributions, employment rates, demographic characteristics, and regional employment patterns. Provides district-level statistics and historical time series that can be investigated for Duisburg during the 2000s. Useful for comparing employment developments across regions and demographic groups."
    },
    {
      "title": "North Rhine-Westphalia – Employees Subject to Social Insurance Contributions, March 2004",
      "url_or_doi": "https://webshop.it.nrw.de/gratis/A659%20200441.pdf",
      "justification": "Official dataset from the North Rhine-Westphalia statistical authority containing employment figures for March 31, 2004. Includes Duisburg-specific employment counts, with breakdowns by gender, occupational status, and nationality. Reports 154,963 employees subject to social insurance contributions at workplaces in Duisburg. Useful for detailed analysis of employment composition during the early 2000s."
    },
    {
      "title": "North Rhine-Westphalia – Employees Subject to Social Insurance Contributions, September 2004",
      "url_or_doi": "https://webshop.it.nrw.de/gratis/A659%20200443.pdf",
      "justification": "Official regional employment dataset containing statistics for September 30, 2004. Includes employment figures for Duisburg and other municipalities in North Rhine-Westphalia, classified by gender, occupational status, and nationality. Records 155,635 employees subject to social insurance contributions in Duisburg. Useful for examining within-year employment changes and regional differences."
    },
    {
      "title": "North Rhine-Westphalia – Employees Subject to Social Insurance Contributions, March 2005",
      "url_or_doi": "https://webshop.it.nrw.de/gratis/A659%20200541.pdf",
      "justification": "Official employment statistics for March 31, 2005, covering Duisburg and other districts in North Rhine-Westphalia. Provides employment counts disaggregated by gender, nationality, and full-time or part-time status. Reports 150,749 employees subject to social insurance contributions in Duisburg. Valuable for investigating employment structure and changes between 2004 and 2005."
    },
    {
      "title": "North Rhine-Westphalia – Employees Subject to Social Insurance Contributions, December 2003",
      "url_or_doi": "https://www.destatis.de/GPStatistik/servlets/MCRFileNodeServlet/NWHeft_derivate_00002361/A653200344_A.pdf",
      "justification": "Historical official employment dataset providing district-level statistics for December 31, 2003. Includes Duisburg employment figures disaggregated by gender, occupational status, and nationality. Reports 156,790 employees subject to social insurance contributions in Duisburg. Particularly useful as an early-2000s reference point when analyzing changes in the city's employment structure."
    },
    {
      "title": "Federal Employment Agency – Employment Time Series API",
      "url_or_doi": "https://statistik.arbeitsagentur.de/DE/Statischer-Content/Service/API/API-BST-Zeitreihe.html",
      "justification": "Official API documentation for accessing regional employment time series from the German Federal Employment Agency. Supports employment statistics at district and independent-city level, making Duisburg a relevant geographical unit. Provides machine-readable access to employment indicators and is useful for constructing longitudinal datasets. Historical coverage for the requested years should be verified before extraction."
    },
    {
      "title": "GovData – Social Insurance Employment Statistics for Duisburg",
      "url_or_doi": "https://www.govdata.de/suche/daten/sozialversicherungspflichte-beschaftigte",
      "justification": "German government open-data catalog entry for Duisburg employment statistics sourced from the Federal Employment Agency. Provides downloadable employment data in CSV and JSON formats. The catalog is useful for identifying structured municipal employment datasets, although the listed releases primarily cover more recent years rather than the 2000–2009 period."
    },
    {
      "title": "Open Data Portal Ruhr – Social Insurance Employment Statistics",
      "url_or_doi": "https://opendata.metropoleruhr.de/dataset/sozialversicherungspflichte-beschaftigte",
      "justification": "Regional open-data portal containing employment statistics for Duisburg, based on administrative employment records. Offers downloadable structured datasets on employees subject to social insurance contributions. Relevant for regional comparisons and potentially linking historical employment figures with more recent observations. Availability of records from 2000–2009 requires verification."
    }
  ]
}
